style.css:
/* Google text ko hide karke apna naam dikhane ke liye */
[aria-label="Google"] {
    font-size: 0 !important;
}

[aria-label="Google"]::before {
    content: "Abhishek Mishra";   /* Aapka naam */
    font-size: 92px !important;
    font-weight: bold;
    font-family: 'Product Sans', Arial, sans-serif;
    background: linear-gradient(to right, #4285F4 20%, #EA4335 40%, #FBBC05 60%, #34A853 80%, #4285F4 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}
